<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {open} from '@tauri-apps/plugin-dialog'
import {command,message,desktop} from '../api'
interface Backup{name:string;bytes:number;modified:string}
const backups=ref<Backup[]>([]),busy=ref(false),error=ref(''),success=ref(''),restoreOpen=ref(false),selected=ref<Backup>(),password=ref(''),confirmation=ref('')
async function load(){try{backups.value=await command('list_backups')}catch(e){error.value=message(e)}}
async function backup(){busy.value=true;error.value='';try{success.value='Создана и проверена копия: '+await command<string>('create_backup');await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function importCopy(){busy.value=true;error.value='';try{const path=await open({multiple:false,filters:[{name:'База Кабинета УЗИ',extensions:['db']}]});if(typeof path==='string'){await command('import_backup',{path});success.value='Копия проверена и добавлена в список. Текущая база не изменена.';await load()}}catch(e){error.value=message(e)}finally{busy.value=false}}
function prepare(item:Backup){selected.value=item;password.value='';confirmation.value='';restoreOpen.value=true}
async function restore(){if(!selected.value||confirmation.value!=='ВОССТАНОВИТЬ')return;busy.value=true;error.value='';try{await command('restore_backup',{name:selected.value.name,password:password.value});window.location.reload()}catch(e){error.value=message(e)}finally{password.value='';busy.value=false}}
onMounted(load)
</script>
<template><section class="settings-section"><h2 class="mb-4">Резервные копии и восстановление</h2><p class="text-slate-600 leading-relaxed">Ежедневная копия создаётся перед первым сохранением за день. Перед обновлением формата и восстановлением создаётся отдельная страховочная копия. Вложения входят в копию. Старые копии не удаляются автоматически.</p><p class="text-slate-600 mt-3">Периодически переносите копии на другой носитель: тот же диск не защищает от его поломки.</p><div class="flex flex-wrap gap-3 my-6"><UButton icon="i-lucide-hard-drive-download" :loading="busy" :disabled="!desktop" @click="backup">Создать копию</UButton><UButton variant="outline" :disabled="busy||!desktop" @click="importCopy">Добавить копию с носителя</UButton></div><UAlert v-if="error" color="error" variant="soft" :description="error" class="mb-5"/><UAlert v-if="success" color="success" variant="soft" :description="success" class="mb-5"/><div class="table-scroll"><table class="patient-table"><thead><tr><th>Файл</th><th>Размер</th><th>Действие</th></tr></thead><tbody><tr v-for="item in backups" :key="item.name"><td>{{item.name}}</td><td class="whitespace-nowrap">{{(item.bytes/1024/1024).toFixed(1)}} МБ</td><td><UButton variant="outline" :disabled="busy" @click="prepare(item)">Восстановить</UButton></td></tr><tr v-if="!backups.length"><td colspan="3">Копий пока нет</td></tr></tbody></table></div><UModal v-model:open="restoreOpen" title="Восстановить базу?" :description="selected?.name" :dismissible="!busy" :ui="{content:'max-w-[650px]'}"><template #body><form id="restore-form" @submit.prevent="restore" class="space-y-6"><UAlert color="warning" variant="soft" title="Текущие данные будут заменены данными из копии" description="Программа проверит файл и сохранит текущую базу страховочной копией. Учётные записи тоже вернутся к состоянию из копии. После восстановления потребуется вход."/><UAlert v-if="error" color="error" variant="soft" :description="error"/><UFormField label="Пароль текущего администратора"><UInput v-model="password" type="password" required autocomplete="current-password" class="w-full"/></UFormField><UFormField label="Введите ВОССТАНОВИТЬ для подтверждения"><UInput v-model="confirmation" required autocomplete="off" class="w-full"/></UFormField></form></template><template #footer><UButton variant="ghost" color="neutral" :disabled="busy" @click="restoreOpen=false">Отмена</UButton><UButton type="submit" form="restore-form" color="warning" :disabled="confirmation!=='ВОССТАНОВИТЬ'||!password" :loading="busy">Восстановить базу</UButton></template></UModal></section></template>
